# Title matching is deliberately conservative: unmatched assets are not assumed never made.
def song_key(t):
 t=unicodedata.normalize('NFKD',t.lower().replace('ø','o').replace('’','').replace("'",'')).encode('ascii','ignore').decode()
 return ' '.join(re.sub('[^a-z0-9]+',' ',t).split())
def support_for(song,lead_id,window=None):
 matches=[v for v in V.values() if v['id']!=lead_id and song_key(song) in song_key(v['title']) and (not window or window[0]<=v['publishedAt'][:10]<=window[1])]
 def is_story(v):return any(t in song_key(v['title']) for t in ['behind the scenes','behindthesong','behind the song','the making of','writing','interview'])
 return {'audio':[v['id'] for v in matches if v['durationSec']>62 and 'official audio' in song_key(v['title']) and not any(t in song_key(v['title']) for t in ['demo','remix','reimagined'])],'live':[v['id'] for v in matches if v['durationSec']>62 and any(t in song_key(v['title']) for t in ['live','session','festive festival']) and not is_story(v)],'lyric':[v['id'] for v in matches if v['durationSec']>62 and 'lyric' in song_key(v['title'])],'story':[v['id'] for v in matches if is_story(v)],'alternate':[v['id'] for v in matches if v['durationSec']>62 and any(t in song_key(v['title']) for t in ['acoustic','orchestral','demo','remix','reimagined','karaoke'])],'short':[v['id'] for v in matches if 0<v['durationSec']<=62 and v['publishedAt'][:10]>='2020-09-14']}
def audit_cell(ids):
 if not ids:return '<span class="audit-missing">Not found</span>'
 best=max(ids,key=lambda i:V[i]['views']);titles='; '.join(V[i]['title'] for i in ids)
 return f'<a class="audit-found" href="https://www.youtube.com/watch?v={best}" target="_blank" rel="noopener" title="{esc(titles)}">Found · {len(ids)} ↗</a>'
